<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarReferencias, obtenerCargos, obtenerOpcionesRegistro, registrarDocumento } from '../services/documentos'
import type { CatalogOption, DocumentoDestino } from '../../interfaces/documento'

const tipos=ref<CatalogOption[]>([]), instancias=ref<CatalogOption[]>([])
const contexto=reactive<{instancia?:CatalogOption|null;cargo?:CatalogOption|null}>({})
const form=reactive({tipo_documento_id:0,asunto:'',prioridad:'Normal',archivo:null as File|null})
const destinos=ref<DocumentoDestino[]>([]), anexos=ref<Array<{archivo:File|null;descripcion:string}>>([])
const referencias=ref<Array<{id:number;text:string}>>([]), resultados=ref<Array<{id:number;text:string}>>([]), referenciaQuery=ref('')
const loading=ref(true),saving=ref(false),error=ref(''),success=ref('')

function nuevoDestino():DocumentoDestino{return{instancia_id:0,cargo_id:0,tipo_tramite:destinos.value.some(d=>d.tipo_tramite==='Original')?'Con Copia':'Original',indicacion:'',tramite:'',cargos:[]}}
function addDestino(){destinos.value.push(nuevoDestino())}
function removeDestino(index:number){if(destinos.value.length>1)destinos.value.splice(index,1)}
async function loadCargos(destino:DocumentoDestino){destino.cargo_id=0;destino.cargos=[];if(!destino.instancia_id)return;destino.loading=true;try{destino.cargos=await obtenerCargos(destino.instancia_id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron cargar los cargos.'}finally{destino.loading=false}}
function principalFile(event:Event){form.archivo=(event.target as HTMLInputElement).files?.[0]||null}
function anexoFile(index:number,event:Event){const anexo=anexos.value[index];if(anexo)anexo.archivo=(event.target as HTMLInputElement).files?.[0]||null}
async function searchRefs(){if(referenciaQuery.value.trim().length<2){resultados.value=[];return}try{resultados.value=await buscarReferencias(referenciaQuery.value.trim())}catch{resultados.value=[]}}
function addRef(item:{id:number;text:string}){if(!referencias.value.some(r=>r.id===item.id))referencias.value.push(item);referenciaQuery.value='';resultados.value=[]}
function validate(){if(!form.tipo_documento_id)return'Debe elegir un tipo de documento.';if(!form.asunto.trim())return'El asunto es obligatorio.';if(!destinos.value.length)return'Debe agregar un destino.';if(destinos.value.some(d=>!d.instancia_id||!d.cargo_id))return'Complete la instancia y el cargo de cada destino.';if(!destinos.value.some(d=>d.tipo_tramite==='Original'))return'Al menos un destino debe recibir el documento como Original.';if(anexos.value.some(a=>!a.archivo))return'Seleccione el archivo de cada anexo.';return''}
async function submit(){error.value=validate();success.value='';if(error.value)return;const data=new FormData();data.append('tipo_documento_id',String(form.tipo_documento_id));data.append('asunto',form.asunto);data.append('prioridad',form.prioridad);if(form.archivo)data.append('archivo',form.archivo);destinos.value.forEach((d,i)=>{data.append(`destinos[${i}][instancia_id]`,String(d.instancia_id));data.append(`destinos[${i}][cargo_id]`,String(d.cargo_id));data.append(`destinos[${i}][tipo_tramite]`,d.tipo_tramite);data.append(`destinos[${i}][indicacion]`,d.indicacion);data.append(`destinos[${i}][tramite]`,d.tramite)});anexos.value.forEach((a,i)=>{if(a.archivo)data.append(`anexos[${i}][archivo]`,a.archivo);data.append(`anexos[${i}][descripcion]`,a.descripcion)});referencias.value.forEach(r=>data.append('referencias[]',String(r.id)));saving.value=true;try{const r=await registrarDocumento(data);success.value=r.message||`Documento #${r.id} registrado correctamente.`;Object.assign(form,{tipo_documento_id:0,asunto:'',prioridad:'Normal',archivo:null});destinos.value=[nuevoDestino()];anexos.value=[];referencias.value=[]}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo registrar el documento.'}finally{saving.value=false}}
onMounted(async()=>{try{const r=await obtenerOpcionesRegistro();tipos.value=r.tipos_documento;instancias.value=r.instancias;contexto.instancia=r.contexto.instancia_activa;contexto.cargo=r.contexto.cargo_activo;addDestino()}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo preparar el formulario.'}finally{loading.value=false}})
</script>

<template><div class="document-page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Gestión de documentos / Registrar</nav><header class="hero"><div class="mark">TR</div><div><small>Gestión de documentos</small><h1>Registrar documento interno</h1><p>Registra el documento y define uno o varios destinos para su posterior envío.</p></div><aside v-if="contexto.instancia"><b>{{contexto.instancia.nombre}}</b><span>{{contexto.cargo?.nombre||'Cargo activo'}}</span></aside></header><div v-if="success" class="alert success">✓ {{success}}</div><div v-if="error" class="alert error">{{error}}</div><div v-if="loading" class="empty">Preparando formulario…</div><form v-else @submit.prevent="submit"><section class="card"><header><div><small>01</small><h2>Datos del documento</h2></div><span>Los campos con * son obligatorios</span></header><div class="grid three"><label><span>Tipo de documento *</span><select v-model="form.tipo_documento_id" required><option :value="0" disabled>Seleccione</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Prioridad *</span><select v-model="form.prioridad"><option>Normal</option><option>Urgente</option><option>Muy urgente</option></select></label><label><span>Archivo principal <em>máx. 20 MB</em></span><input type="file" @change="principalFile"></label><label class="full"><span>Asunto *</span><textarea v-model.trim="form.asunto" maxlength="500" rows="3" placeholder="Descripción breve del asunto"></textarea><small>{{form.asunto.length}}/500</small></label></div></section><section class="card"><header><div><small>02</small><h2>Destinos</h2></div><button type="button" @click="addDestino">+ Agregar destino</button></header><article v-for="(d,index) in destinos" :key="index" class="destination"><div class="destination-title"><b>Destino {{index+1}}</b><button type="button" :disabled="destinos.length===1" @click="removeDestino(index)">Eliminar</button></div><div class="grid three"><label><span>Oficina de destino *</span><select v-model="d.instancia_id" @change="loadCargos(d)"><option :value="0" disabled>Seleccione</option><option v-for="o in instancias" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Cargo de destino *</span><select v-model="d.cargo_id" :disabled="!d.instancia_id||d.loading"><option :value="0" disabled>{{d.loading?'Cargando…':'Seleccione'}}</option><option v-for="o in d.cargos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label><span>Tipo de trámite *</span><select v-model="d.tipo_tramite"><option>Original</option><option>Con Copia</option></select></label><label><span>Trámite</span><input v-model.trim="d.tramite" maxlength="250" placeholder="Descripción del trámite"></label><label class="span-two"><span>Indicaciones</span><input v-model.trim="d.indicacion" placeholder="Instrucciones específicas para este destino"></label></div></article></section><section class="card"><header><div><small>03</small><h2>Anexos y referencias</h2></div><button type="button" @click="anexos.push({archivo:null,descripcion:''})">+ Agregar anexo</button></header><div v-if="anexos.length" class="attachments"><div v-for="(a,index) in anexos" :key="index"><input type="file" @change="anexoFile(index,$event)"><input v-model.trim="a.descripcion" placeholder="Descripción del anexo"><button type="button" @click="anexos.splice(index,1)">×</button></div></div><label class="reference"><span>Buscar documentos de referencia</span><input v-model.trim="referenciaQuery" placeholder="Número o asunto (mínimo 2 caracteres)" @input="searchRefs"><ul v-if="resultados.length"><li v-for="r in resultados" :key="r.id" @click="addRef(r)">{{r.text}}</li></ul></label><div class="chips"><span v-for="r in referencias" :key="r.id">{{r.text}} <button type="button" @click="referencias=referencias.filter(x=>x.id!==r.id)">×</button></span></div></section><footer class="form-actions"><RouterLink to="/modulos/tramite/documentos">Cancelar</RouterLink><button type="submit" :disabled="saving">{{saving?'Registrando…':'Registrar documento'}}</button></footer></form></div></template>

<style scoped>
.document-page{--accent:#2878d0;color:#33454e}nav{margin-bottom:17px;color:#99a5ab;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero,.card{border:1px solid #e2e8ec;border-radius:13px;background:#fff;box-shadow:0 5px 20px #233d4b0b}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent)}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-weight:700}.hero small,.card header small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero aside{margin-left:auto;text-align:right}.hero aside b,.hero aside span{display:block;font-size:.68rem}.hero aside span{color:#89959b}.alert{margin-top:14px;padding:11px 13px;border-radius:8px;font-size:.7rem}.alert.error{color:#963e3e;border:1px solid #efcaca;background:#fff4f4}.alert.success{color:#246c50;border:1px solid #badfce;background:#eff9f4}.empty{margin-top:15px;padding:50px;text-align:center;background:#fff}.card{margin-top:16px;padding:20px}.card>header{display:flex;align-items:center;margin-bottom:18px;padding-bottom:13px;border-bottom:1px solid #edf0f2}.card h2{margin:2px 0;font-size:.92rem}.card>header>span{margin-left:auto;color:#89959b;font-size:.62rem}.card>header button,.form-actions>button{margin-left:auto;padding:8px 12px;border:0;border-radius:7px;color:#fff;background:var(--accent);font-size:.65rem}.grid{display:grid;gap:13px}.grid.three{grid-template-columns:repeat(3,1fr)}label>span{display:block;margin-bottom:6px;color:#65737a;font-size:.65rem;font-weight:600}label em{float:right;color:#9aa5aa;font-size:.56rem;font-style:normal}input,select,textarea{width:100%;border:1px solid #dbe3e7;border-radius:7px;background:#fff;font:inherit;font-size:.7rem;outline:0}input,select{height:40px;padding:0 10px}input[type=file]{padding:8px}textarea{padding:10px;resize:vertical}.full{grid-column:1/-1}.span-two{grid-column:span 2}.full>small{float:right;color:#9aa5aa;font-size:.57rem}.destination{padding:14px;border:1px solid #e5eaed;border-radius:9px;background:#fafbfc}.destination+.destination{margin-top:10px}.destination-title{margin-bottom:12px;display:flex;font-size:.68rem}.destination-title button{margin-left:auto;border:0;color:#b44a4a;background:none;font-size:.62rem}.attachments>div{display:grid;grid-template-columns:1fr 1fr 35px;gap:8px;margin-bottom:8px}.attachments button{border:0;border-radius:6px;color:#a54242;background:#ffeded}.reference{position:relative;display:block;margin-top:14px}.reference ul{position:absolute;z-index:3;left:0;right:0;margin:2px 0;padding:5px;list-style:none;border:1px solid #dce3e7;border-radius:7px;background:#fff;box-shadow:0 8px 20px #1b344422}.reference li{padding:8px;border-radius:5px;font-size:.66rem;cursor:pointer}.reference li:hover{background:#edf4fc}.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.chips>span{padding:6px 8px;border-radius:15px;color:#28699d;background:#eaf3fb;font-size:.61rem}.chips button{border:0;background:none}.form-actions{padding:18px 0;display:flex;justify-content:flex-end;gap:8px}.form-actions a{padding:9px 13px;border:1px solid #d8e0e4;border-radius:7px;color:#66747b;text-decoration:none;font-size:.66rem}.form-actions>button{margin:0;padding:10px 16px}@media(max-width:850px){.grid.three{grid-template-columns:1fr 1fr}.full{grid-column:1/-1}.hero{flex-wrap:wrap}.hero aside{width:100%;margin:0;text-align:left}}@media(max-width:580px){.grid.three{grid-template-columns:1fr}.span-two,.full{grid-column:auto}.attachments>div{grid-template-columns:1fr 35px}.attachments>div input:nth-child(2){grid-column:1/-1;grid-row:2}.card{padding:15px}}
</style>
